#!/usr/bin/env python3
from __future__ import annotations
import hashlib,json
from pathlib import Path
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve()
while ROOT!=ROOT.parent and not (ROOT/'AGENTS.md').exists(): ROOT=ROOT.parent
REV=Path(__file__).resolve().parent; W=240; H=320
BODY=ROOT/'assets/characters/hero/battle45/cast_rightup_3.png'; SOURCE=ROOT/'assets/_trial_20260908/t45_hero_weapon_pilot_frame01_codex_native/revisions/handle-center-half-length-v9/normalized/hero_sword_held_rightup_v9.png'
RAW=REV/'raw/original_cast_rightup_3_body.png'; OUT=REV/'normalized/hero_sword_angle_minus80_cast_rightup_3_original_body_v2.png'; CONTACT=REV/'contact/hero_cast_rightup_3_original_body_sword_minus80_v2.png'; CONTACT2=REV/'contact/hero_cast_rightup_3_original_body_sword_minus80_v2_2x.png'; ZOOM=REV/'contact/cast_rightup_3_original_body_angle10_zoom_v2.png'; QA=REV/'qa/pilot_cast_rightup_3_original_body_angle10_v2.json'; CAL=REV/'calibration/frame19_cast_rightup_3_original_body_angle10_v2.json'; MANIFEST=REV/'manifest.json'; JOB=REV/'job.json'; REFS=REV/'refs.json'; PROMPT=REV/'prompts/body_front_no_mask.txt'
SOURCE_HANDLE=(101.57368615160715,205.58781573590227); FIST=(190.0,211.0); HANDLE=(190.57368615160715,210.58781573590227); ROTATE_DEG=-50.0; SHIFT=(89,5); SCREEN_ANGLE=10.0
